"},"$:/plugins/huwiki/hupedia/kind.js":{"title":"$:/plugins/huwiki/hupedia/kind.js","type":"application/javascript","module-type":"filteroperator","text":"/* Shared tag precedence for article views and edit forms. */
"use strict";

var kinds = [
  ["Person"],
  ["Sted", "Place"],
  ["Begivenhed", "Event"],
  ["Organisation", "Organization"],
  ["Musikværk", "MusicalWork"],
  ["Begreb", "Concept"],
  ["Artikel", "Article"]
];

exports["hupedia-kind"] = function(source, operator, options) {
  var output = [];

  source(function(tiddler, title) {
    if (!tiddler || String(title).indexOf("$:/") === 0) {
      return;
    }

    var tags = tiddler.fields.tags || [];
    for (var i = 0; i < kinds.length; i++) {
      var matches = kinds[i].some(function(kind) {
        return tags.indexOf("HUPedia/" + kind) >= 0;
      });

      if (matches) {
        output.push(kinds[i][0]);
        return;
      }
    }

    if (tags.indexOf("PediaArtikel") >= 0) {
      output.push("Artikel");
    }
  });

  return output;
};
"},"$:/plugins/huwiki/hupedia/article-view":{"title":"$:/plugins/huwiki/hupedia/article-view","type":"text/vnd.tiddlywiki","text":"\whitespace trim
