[<currentTiddler>tag[HUPedia/Localized]then[$:/plugins/huwiki/hupedia/localized-body]]
"},"$:/plugins/huwiki/hupedia/style.css":{"title":"$:/plugins/huwiki/hupedia/style.css","type":"text/css","tags":"$:/tags/Stylesheet","text":"/* HUPedia components work with or without the optional HUPedia theme. */
.hupedia-article {
  display: flow-root;
  container-type: inline-size;
}

.hupedia-infobox {
  float: right;
  box-sizing: border-box;
  width: 18rem;
  max-width: 46%;
  margin: 0 0 1.25rem 1.5rem;
  padding: 1rem;
  border: 1px solid var(--hupedia-border, #a2a9b1);
  background: var(--hupedia-surface, #f8f9fa);
  color: var(--hupedia-text, #202122);
  font-size: 0.9rem;
  line-height: 1.5;
}

.hupedia-infobox h3 {
  margin: 0 0 1rem;
  padding: 0.65rem;
  background: var(--hupedia-accent-soft, #dbe6f2);
  font: bold 1.15em Georgia, serif;
  text-align: center;
}

.hupedia-infobox dl {
  display: grid;
  grid-template-columns: minmax(0, 0.8fr) minmax(0, 1.2fr);
  gap: 0.6rem 0.75rem;
  margin: 0;
}

.hupedia-infobox dt {
  font-weight: 700;
}

.hupedia-infobox dt,
.hupedia-infobox dd {
  min-width: 0;
  margin: 0;
  overflow-wrap: break-word;
}

.hupedia-article-text > :first-child {
  margin-top: 0;
}

.hupedia-backlinks {
  clear: both;
  margin-top: 1.5rem;
  padding-top: 0.85rem;
  border-top: 1px solid var(--hupedia-border, #c8ccd1);
  color: var(--hupedia-muted, #54595d);
  font-size: 0.9em;
}

.hupedia-backlinks ul {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem 1.5rem;
  margin: 0.5rem 0 0;
  padding-left: 1.25rem;
}

.hupedia-edit-form {
  clear: both;
  margin: 1rem 0;
  padding: 1rem;
  border: 1px solid var(--hupedia-border, #a2a9b1);
  border-radius: 0.25rem;
  background: var(--hupedia-surface, #f8f9fa);
  color: var(--hupedia-text, #202122);
}

.hupedia-form-title {
  margin: 0 0 1rem;
  font: bold 1.1rem Georgia, serif;
}

.hupedia-form-title span {
  display: block;
  margin-top: 0.35rem;
  color: var(--hupedia-muted, #54595d);
  font: normal 0.85rem system-ui, sans-serif;
}

.hupedia-form-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 14rem), 1fr));
  gap: 0.85rem;
}

.hupedia-form-row {
  display: flex;
  flex-direction: column;
  min-width: 0;
  gap: 0.3rem;
  font: 0.85rem system-ui, sans-serif;
}

.hupedia-form-row .hupedia-input {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  padding: 0.5rem;
  border: 1px solid var(--hupedia-border, #a2a9b1);
  border-radius: 0.2rem;
  background: #fff;
  color: #202122;
}

.hupedia-form-hint {
  margin: 1rem 0 0;
  color: var(--hupedia-muted, #54595d);
  font-size: 0.85em;
}

/* Measure the article, not the screen: the HUWiki sidebar can stay open. */
@container (max-width: 35rem) {
  .hupedia-infobox {
    float: none;
    width: 100%;
    max-width: none;
    margin: 0 0 1.25rem;
  }
}

/* Fallback for browsers without container queries. */
@media (max-width: 600px) {
  .hupedia-infobox {
    float: none;
    width: 100%;
    max-width: none;
    margin: 0 0 1.25rem;
  }
}

/* Keep translated WikiText easy to edit, with explicit source line breaks. */
.hupedia-translation-editor { margin: 1rem 0; padding: 0.9rem 1rem; border: 1px solid var(--hupedia-border,#a2a9b1); background: var(--hupedia-surface,#f8f9fa); }
.hupedia-translation-editor summary { font-weight: 700; cursor: pointer; }
.hupedia-translation-editor p { margin: 0.75rem 0; }
.hupedia-translation-textarea { display: block; box-sizing: border-box; min-height: 16rem; width: 100%; max-width: 100%; font: 0.94rem/1.55 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; white-space: pre-wrap; }
"},"$:/plugins/huwiki/hupedia/localized-body":{"title":"$:/plugins/huwiki/hupedia/localized-body","type":"text/vnd.tiddlywiki","text":"\whitespace trim

<!--
  Language selection belongs in this template, not in article source.
  English is optional. Ordinary WikiText in "text" stays readable/editable.
  Explicit block transclusion is essential for ! headings and * lists.
-->
<$list filter="[{$:/language}else[$:/languages/en-GB]!prefix[$:/languages/da]]" variable="hupediaLocale">

  <$list filter="[<currentTiddler>has[text-en]]" variable="hupediaEnglish">

    <$transclude $field="text-en" $type="text/vnd.tiddlywiki" $mode="block"/>

  </$list>

  <$list filter="[<currentTiddler>!has[text-en]]" variable="hupediaFallback">

    <$transclude $tiddler="$:/core/ui/ViewTemplate/body/default" $mode="block"/>

  </$list>

</$list>

<$list filter="[{$:/language}else[$:/languages/en-GB]prefix[$:/languages/da]]" variable="hupediaLocale">

  <$transclude $tiddler="$:/core/ui/ViewTemplate/body/default" $mode="block"/>

</$list>
"},"$:/plugins/huwiki/hupedia/english-editor":{"title":"$:/plugins/huwiki/hupedia/english-editor","type":"text/vnd.tiddlywiki","tags":"$:/tags/EditTemplate","text":"\whitespace trim

<!-- Extra multiline editor; TiddlyWiki's own language selection controls preview. -->
<$list filter="[<currentTiddler>has[text-en]] [<currentTiddler>tag[HUPedia/Localized]] [<currentTiddler>hupedia-kind[]!match[]] +[unique[]]" variable="hupediaLocalizable">

  <details class="hupedia-translation-editor">

    <summary>
      <$list filter="[{$:/language}else[$:/languages/en-GB]prefix[$:/languages/da]]" variable="hupediaLocale">Engelsk artikeltekst (valgfri)</$list>
      <$list filter="[{$:/language}else[$:/languages/en-GB]!prefix[$:/languages/da]]" variable="hupediaLocale">English article text (optional)</$list>
    </summary>

    <$list filter="[{$:/language}else[$:/languages/en-GB]prefix[$:/languages/da]]" variable="hupediaLocale">
      <p>Redigér den engelske version som almindelig WikiText. Bevar tomme linjer mellem afsnit, og brug ! til overskrifter. Det danske indhold redigeres i TiddlyWikis normale tekstfelt.</p>
    </$list>

    <$list filter="[{$:/language}else[$:/languages/en-GB]!prefix[$:/languages/da]]" variable="hupediaLocale">
      <p>Edit English as normal WikiText. Leave blank lines between paragraphs and use ! for headings. Edit Danish in TiddlyWiki's usual text editor.</p>
    </$list>

    <$edit-text field="text-en" tag="textarea" rows="16" autoHeight="yes" class="tc-edit-texteditor hupedia-translation-textarea" />

  </details>

</$list>
"},"$:/plugins/huwiki/hupedia/forms/Person/da":{"title":"$:/plugins/huwiki/hupedia/forms/Person/da","type":"text/vnd.tiddlywiki","text":"\whitespace trim

